--- /dev/null
+++ b/packs/claudinite-growth/test/dedup-integrity.test.mjs
@@ -0,0 +1,56 @@
+import { test } from &#39;node:test&#39;;
+import assert from &#39;node:assert/strict&#39;;
+import rule from &#39;../workRules/dedup-integrity.mjs&#39;;
+
+const RULES = &#39;.claudinite/local/packs/demo/RULES.md&#39;;
+const VERSIONS = &#39;.claudinite/local/packs/demo/VERSIONS.md&#39;;
+
+// The work context the rule reads — only the members it calls.
+const work = ({ commits = [&#39;Claudinite growth: dedup local packs&#39;], changedFiles, files, base, added = [] }) =&gt; ({
+  branch: &#39;claude/some-branch&#39;,
+  onDefaultBranch: () =&gt; false,
+  commits,
+  changedFiles,
+  read: (f) =&gt; files[f] ?? null,
+  readBase: (f) =&gt; base[f] ?? null,
+  addedLines: () =&gt; added,
+});
+
+test(&#39;a dedup run that shrinks RULES.md while VERSIONS.md grows with the required log row is clean&#39;, () =&gt; {
+  const findings = rule.run(work({
+    changedFiles: [RULES, VERSIONS],
