+    base: { [RULES]: &#39;a\nb\nc\nd\n&#39;, [VERSIONS]: &#39;# log\n\n| Date | Task | Change |\n|---|---|---|\n&#39; },
+  }));
+  assert.deepEqual(findings, []);
+});
+
+test(&#39;a dedup run that grows RULES.md itself still fires, VERSIONS.md exemption or not&#39;, () =&gt; {
+  const findings = rule.run(work({
+    changedFiles: [RULES],
+    files: { [RULES]: &#39;a\nb\nc\n&#39; },
+    base: { [RULES]: &#39;a\nb\n&#39; },
+  }));
+  assert.equal(findings.length, 1);
+  assert.equal(findings[0].file, RULES);
+  assert.match(findings[0].what, /grew .*RULES\.md from 3 to 4 lines/);
+});
+
+test(&#39;VERSIONS.md alone growing in a dedup-labeled commit is never a finding&#39;, () =&gt; {
+  const findings = rule.run(work({
+    changedFiles: [VERSIONS],
+    files: { [VERSIONS]: &#39;one\ntwo\nthree\n&#39; },
+    base: { [VERSIONS]: &#39;one\n&#39; },
+  }));
+  assert.deepEqual(findings, []);
+});
+
+test(&#39;a non-dedup-labeled commit is never held to the shrink invariant, VERSIONS.md included&#39;, () =&gt; {
+  const findings = rule.run(work({
+    commits: [&#39;Claudinite growth: extract lessons&#39;],
+    changedFiles: [RULES, VERSIONS],
+    files: { [RULES]: &#39;a\nb\nc\n&#39;, [VERSIONS]: &#39;one\ntwo\n&#39; },
+    base: { [RULES]: &#39;a\n&#39;, [VERSIONS]: &#39;one\n&#39; },
+  }));
+  assert.deepEqual(findings, []);
+});
